import base64, pathlib

# Exact supplied Driver/Mech AI logo, lossless 256px build asset.
data=""
raw=base64.b64decode(data)
out=pathlib.Path("app/src/main/res/drawable")
out.mkdir(parents=True,exist_ok=True)
assets=pathlib.Path("app/src/main/assets")
assets.mkdir(parents=True,exist_ok=True)
(out/"logo_exact.webp").write_bytes(raw)
(assets/"driver_mech_logo.webp").write_bytes(raw)
# Remove stale variants so the APK cannot accidentally pick the old logo.
for p in [out/"logo_exact.jpg", assets/"driver_mech_logo.jpg"]:
    if p.exists(): p.unlink()
